"use strict";(globalThis.webpackChunktechnical_writing_portfolio=globalThis.webpackChunktechnical_writing_portfolio||[]).push([[2162],{1317(e,t,n){n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>s,default:()=>h,frontMatter:()=>r,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"atlas-copco/industrial-dispensing","title":"Henrob blow feed riveting documentation","description":"The Henrob blow feed riveting system presented a unique technical writing challenge at Atlas Copco. This was energy-efficient technology - achieving just 7Wh per rivet while delivering setting forces up to 85,000 N. The engineering was impressive, but making it accessible to production teams required a completely different approach.","source":"@site/docs/atlas-copco/industrial-dispensing.md","sourceDirName":"atlas-copco","slug":"/atlas-copco/industrial-dispensing","permalink":"/portfolio/docs/atlas-copco/industrial-dispensing","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4},"sidebar":"tutorialSidebar","previous":{"title":"Henrob tape feed riveting documentation","permalink":"/portfolio/docs/atlas-copco/flow-drill-fastening"},"next":{"title":"My work at CDW","permalink":"/portfolio/docs/cdw/"}}');var o=n(4848),a=n(8453);const r={sidebar_position:4},s="Henrob blow feed riveting documentation",d={},c=[{value:"Understanding the technology first",id:"understanding-the-technology-first",level:2},{value:"Connecting to broader Atlas Copco experience",id:"connecting-to-broader-atlas-copco-experience",level:2},{value:"Addressing multiple audiences",id:"addressing-multiple-audiences",level:2},{value:"Safety and reliability focus",id:"safety-and-reliability-focus",level:2},{value:"Process optimization documentation",id:"process-optimization-documentation",level:2},{value:"Quality and monitoring integration",id:"quality-and-monitoring-integration",level:2},{value:"Global manufacturing considerations",id:"global-manufacturing-considerations",level:2},{value:"Integration with broader joining solutions",id:"integration-with-broader-joining-solutions",level:2},{value:"Results and continuous improvement",id:"results-and-continuous-improvement",level:2}];function l(e){const t={h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"henrob-blow-feed-riveting-documentation",children:"Henrob blow feed riveting documentation"})}),"\n",(0,o.jsx)(t.p,{children:"The Henrob blow feed riveting system presented a unique technical writing challenge at Atlas Copco. This was energy-efficient technology - achieving just 7Wh per rivet while delivering setting forces up to 85,000 N. The engineering was impressive, but making it accessible to production teams required a completely different approach."}),"\n",(0,o.jsx)(t.h2,{id:"understanding-the-technology-first",children:"Understanding the technology first"}),"\n",(0,o.jsx)(t.p,{children:"Before I could write a single word, I needed to understand why blow feed was different from tape feed systems. The magazine rivet feed mechanism was more complex than it appeared - pneumatic systems controlling rivet selection, positioning, and the actual riveting process all had to work in perfect synchronization."}),"\n",(0,o.jsx)(t.p,{children:"I spent weeks with the engineering team, not just learning what each component did, but understanding the decisions behind the design. Why this pneumatic approach instead of mechanical feed? How did the energy efficiency improvements actually work? These weren't just technical details - they were the story I needed to tell."}),"\n",(0,o.jsx)(t.h2,{id:"connecting-to-broader-atlas-copco-experience",children:"Connecting to broader Atlas Copco experience"}),"\n",(0,o.jsx)(t.p,{children:"This project built directly on the self-pierce riveting work I had already completed. The fundamental joining technology was similar, but the delivery method changed everything about how operators would interact with the system. I could reference the foundation I had built in the main riveting documentation while highlighting what made blow feed special."}),"\n",(0,o.jsx)(t.p,{children:"Like the webhooks security documentation I later wrote at Ably, this required explaining complex interactions between multiple systems. The blow feed mechanism, the riveting head, the control system, and the quality monitoring all had to work together seamlessly."}),"\n",(0,o.jsx)(t.h2,{id:"addressing-multiple-audiences",children:"Addressing multiple audiences"}),"\n",(0,o.jsx)(t.p,{children:"Production managers cared about the 7Wh energy efficiency and what that meant for operating costs. Technicians needed to understand the magazine loading procedures and troubleshooting steps. Quality engineers wanted to know about the 85,000 N force capability and how to monitor joint integrity."}),"\n",(0,o.jsx)(t.p,{children:"I structured the documentation with clear paths for each audience, similar to how I later organized the developer journey mapping at Ably. Different users had different entry points and different goals, but they all needed to understand how their work connected to the overall system performance."}),"\n",(0,o.jsx)(t.h2,{id:"safety-and-reliability-focus",children:"Safety and reliability focus"}),"\n",(0,o.jsx)(t.p,{children:"Blow feed systems operate at much higher forces than most manufacturing equipment. The 85,000 N setting force could cause serious injury if safety protocols weren't followed correctly. Every procedure had to start with safety considerations, and I had to make those warnings clear without being overwhelming."}),"\n",(0,o.jsx)(t.p,{children:"I developed a layered safety approach - immediate safety warnings for dangerous operations, general safety guidelines for each section, and comprehensive safety training materials for new operators. This mirrors the contextual approach I used in troubleshooting guides at Ably, where different situations required different levels of detail."}),"\n",(0,o.jsx)(t.h2,{id:"process-optimization-documentation",children:"Process optimization documentation"}),"\n",(0,o.jsx)(t.p,{children:"The most interesting part of this project was documenting how to optimize the blow feed process for different production requirements. The energy efficiency wasn't just a marketing feature - it had real implications for production planning and facility requirements."}),"\n",(0,o.jsx)(t.p,{children:"I worked with applications engineers to understand how different rivet materials, joint configurations, and production speeds affected energy consumption and cycle times. This became some of the most valuable content for production engineers planning new installations."}),"\n",(0,o.jsx)(t.h2,{id:"quality-and-monitoring-integration",children:"Quality and monitoring integration"}),"\n",(0,o.jsx)(t.p,{children:"Blow feed systems generate different force and energy signatures than other riveting methods. I had to create documentation that helped quality teams understand what these signatures meant and how to use them for process control."}),"\n",(0,o.jsx)(t.p,{children:"This connected to the broader troubleshooting approach I had developed for Atlas Copco - systematic diagnostic procedures that helped operators identify issues quickly and accurately. The energy efficiency meant smaller margins for error, so the monitoring and response procedures had to be more precise."}),"\n",(0,o.jsx)(t.h2,{id:"global-manufacturing-considerations",children:"Global manufacturing considerations"}),"\n",(0,o.jsx)(t.p,{children:"These systems were shipping to automotive plants worldwide, each with different quality standards, safety regulations, and operator skill levels. The documentation had to work equally well for a highly automated German plant and a more manual facility in Mexico."}),"\n",(0,o.jsx)(t.p,{children:"I created modular documentation that could be adapted for different markets while maintaining technical consistency. This experience later influenced how I approached content restructuring at Ably - different markets and user types needed different presentations of the same core information."}),"\n",(0,o.jsx)(t.h2,{id:"integration-with-broader-joining-solutions",children:"Integration with broader joining solutions"}),"\n",(0,o.jsx)(t.p,{children:"Blow feed riveting didn't exist in isolation - it was part of Atlas Copco's complete joining portfolio. I made sure the documentation clearly explained when blow feed was the right choice versus tape feed or other methods."}),"\n",(0,o.jsx)(t.p,{children:"This systems thinking became central to how I approached technical writing throughout my career. Individual technologies are just components in larger solutions, and documentation needs to help users understand those connections."}),"\n",(0,o.jsx)(t.h2,{id:"results-and-continuous-improvement",children:"Results and continuous improvement"}),"\n",(0,o.jsx)(t.p,{children:"The blow feed documentation became a reference for other product lines because of its clear structure and practical focus. More importantly, it helped reduce the implementation time for new installations and improved troubleshooting efficiency when production issues occurred."}),"\n",(0,o.jsx)(t.p,{children:"The feedback from field applications helped identify areas where the documentation could be clearer, leading to continuous improvements that benefited everyone using these systems. This user feedback approach became a cornerstone of how I approached documentation projects at every subsequent company."})]})}function h(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(6540);const o={},a=i.createContext(o);function r(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);